#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ll a, b, c, l;
    cin >> a >> b >> c >> l;
    ll ans = 0;
    // iterate over x (increase for a)
    for (ll x = 0; x <= l; x++) {
        ll rem = l - x;
        // iterate over y (increase for b)
        for (ll y = 0; y <= rem; y++) {
            ll zmax = rem - y;
            // z is increase for c
            // we need to count z in [0, zmax] such that
            // (a+x)+(b+y) > (c+z)
            // (a+x)+(c+z) > (b+y)
            // (b+y)+(c+z) > (a+x)
            // Let A = a+x, B = b+y, C = c+z
            // Conditions:
            // A+B > C  =>  C < A+B  =>  z < A+B - c
            // A+C > B  =>  C > B-A  =>  z > B-A - c
            // B+C > A  =>  C > A-B  =>  z > A-B - c
            // So z must satisfy:
            // z >= max(0, B-A-c+1, A-B-c+1)  (since z integer and strict inequality)
            // z <= min(zmax, A+B-c-1)
            ll A = a + x;
            ll B = b + y;
            ll C0 = c;
            ll lower = max(0LL, max(B - A - C0 + 1, A - B - C0 + 1));
            ll upper = min(zmax, A + B - C0 - 1);
            if (upper >= lower) {
                ans += (upper - lower + 1);
            }
        }
    }
    cout << ans << endl;
    return 0;
}
